/**
 * Vendored from shadcn-ui/ui apps/v4/registry/new-york-v4/ui/table.tsx + CapCons.
 */
/**
 * CapCons-enabled shadcn/ui primitive (vendored New York v4) with `capconsSpread` on the root.
 *
 * **Props:** Cross-cutting authoring fields are documented on `CapconsBasePropsLoose` /
 * `CapconsGlobalAuthoring` / `CapconsSectionFields` / `CapconsNavFields` in `@capcons/sdk`.
 * Prefer the strict union `CapconsBaseProps` in app code (one role per node: section, nav, surface, or neutral).
 *
 * Put `section` and block tools (`duplicate`, `reorder`, …) on a **wrapper**; inner nodes stay neutral.
 *
 * @example Wrapper block + neutral button
 * ```tsx
 * <div section sectionLabel="Hero" capconsCapabilities={["duplicate", "reorder"]}>
 *   <Button type="button" editable="text" capconsKind="text">Save</Button>
 * </div>
 * ```
 *
 * @example Editable label
 * ```tsx
 * <Button type="button" editable="text" capconsKind="text">
 *   Edit me
 * </Button>
 * ```
 */
"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { capconsSpread } from "@/lib/capcons-spread";
import type { CapconsBasePropsLoose } from "@/lib/capcons-spread";
function Table({
  className,
  ...props
}: React.ComponentProps<"table"> & CapconsBasePropsLoose) {
  return <div data-slot="table-container" className="relative w-full overflow-x-auto">
      <table data-slot="table" className={cn("w-full caption-bottom text-sm", className)} {...capconsSpread(props)} />
    </div>;
}
function TableHeader({
  className,
  ...props
}: React.ComponentProps<"thead"> & CapconsBasePropsLoose) {
  return <thead data-slot="table-header" className={cn("[&_tr]:border-b", className)} {...capconsSpread(props)} />;
}
function TableBody({
  className,
  ...props
}: React.ComponentProps<"tbody"> & CapconsBasePropsLoose) {
  return <tbody data-slot="table-body" className={cn("[&_tr:last-child]:border-0", className)} {...capconsSpread(props)} />;
}
function TableFooter({
  className,
  ...props
}: React.ComponentProps<"tfoot"> & CapconsBasePropsLoose) {
  return <tfoot data-slot="table-footer" className={cn("border-t bg-muted/50 font-medium [&>tr]:last:border-b-0", className)} {...capconsSpread(props)} />;
}
function TableRow({
  className,
  ...props
}: React.ComponentProps<"tr"> & CapconsBasePropsLoose) {
  return <tr data-slot="table-row" className={cn("border-b transition-colors hover:bg-muted/50 has-aria-expanded:bg-muted/50 data-[state=selected]:bg-muted", className)} {...capconsSpread(props)} />;
}
function TableHead({
  className,
  ...props
}: React.ComponentProps<"th"> & CapconsBasePropsLoose) {
  return <th data-slot="table-head" className={cn("h-10 px-2 text-left align-middle font-medium whitespace-nowrap text-foreground [&:has([role=checkbox])]:pr-0 [&>[role=checkbox]]:translate-y-[2px]", className)} {...capconsSpread(props)} />;
}
function TableCell({
  className,
  ...props
}: React.ComponentProps<"td"> & CapconsBasePropsLoose) {
  return <td data-slot="table-cell" className={cn("p-2 align-middle whitespace-nowrap [&:has([role=checkbox])]:pr-0 [&>[role=checkbox]]:translate-y-[2px]", className)} {...capconsSpread(props)} />;
}
function TableCaption({
  className,
  ...props
}: React.ComponentProps<"caption"> & CapconsBasePropsLoose) {
  return <caption data-slot="table-caption" className={cn("mt-4 text-sm text-muted-foreground", className)} {...capconsSpread(props)} />;
}
export { Table, TableHeader, TableBody, TableFooter, TableHead, TableRow, TableCell, TableCaption };
